    <div id="tradeModal" class="modal"><div class="modal-content"><h3 style="color:var(--gold);">🎰 EXECUTE ARBITRAGE</h3><div id="tradeDetails"></div><div style="margin-top:15px; display:flex; gap:10px; justify-content:flex-end;"><button class="neon-btn" onclick="closeModal()">CANCEL</button><button class="neon-btn cyan" id="executeTradeBtn">💸 PULL LEVER</button></div></div></div>

    <script>
        // ==================== SOUND ENGINE ====================
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        function playTone(freq, duration, type='square', vol=0.1) {
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            osc.type = type;
            osc.frequency.value = freq;
            gain.gain.setValueAtTime(vol, audioCtx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
            osc.connect(gain); gain.connect(audioCtx.destination);
            osc.start(); osc.stop(audioCtx.currentTime + duration);
        }
        function playSpinSound() { playTone(800, 0.1, 'sawtooth', 0.05); }
        function playWinSound() { playTone(523,0.15); setTimeout(()=>playTone(659,0.15),150); setTimeout(()=>playTone(784,0.25),300); }
        function playJackpotSound() { [523,659,784,1047].forEach((f,i)=>setTimeout(()=>playTone(f,0.3,'square',0.15),i*150)); }

        // ==================== PARTICLE SYSTEM ====================
        const canvas = document.getElementById('particleCanvas');
        const ctx = canvas.getContext('2d');
        let particles = [];
        function resizeCanvas() { canvas.width = window.innerWidth; canvas.height = window.innerHeight; }
        window.addEventListener('resize', resizeCanvas); resizeCanvas();
        function spawnConfetti(x,y,count=30) {
            const colors = ['#ff00ff','#00f0ff','#ffd700','#00ffaa'];
            for(let i=0;i<count;i++) {
                particles.push({
                    x:x, y:y, vx:(Math.random()-0.5)*8, vy:(Math.random()-0.5)*8-3, color:colors[Math.floor(Math.random()*colors.length)], life:0.8+Math.random()*0.4
                });
            }
        }
        function animateParticles() {
            ctx.clearRect(0,0,canvas.width,canvas.height);
            for(let i=particles.length-1;i>=0;i--) {
                const p = particles[i];
                p.x += p.vx; p.y += p.vy;
                p.vy += 0.1; p.life -= 0.02;
                ctx.fillStyle = p.color;
                ctx.globalAlpha = p.life;
                ctx.fillRect(p.x,p.y,4,4);
                if(p.life<=0) particles.splice(i,1);
            }
            requestAnimationFrame(animateParticles);
        }
        animateParticles();

        // ==================== STATE ====================
        const state = {
            exchanges: {},
            opportunities: { mega:[], triangular:[], bellman:[], micro:[] },
            stats: { totalPairs:0, graphNodes:0, graphEdges:0, triangleCount:0, apiCalls:0, wsBytes:0, oppCount:0 },
            systemReady: false, graph: {}, triangles: [], allPairs: [],
            bankroll: 10000, trades: []
        };
        function log(msg,type) { const t=new Date().toLocaleTimeString(); const el=document.getElementById('logs'); el.innerHTML=`<div class="log-entry ${type||'info'}">[${t}] ${msg}</div>`+el.innerHTML; console.log(`[${t}] ${msg}`); }
        function updateStatus(msg) { document.getElementById('mainStatus').innerHTML = msg; }
        function updateStats() {
            document.getElementById('totalPairs').textContent = state.stats.totalPairs;
            document.getElementById('graphNodes').textContent = state.stats.graphNodes;
            document.getElementById('graphEdges').textContent = state.stats.graphEdges;
            document.getElementById('triangleCount').textContent = state.stats.triangleCount;
            document.getElementById('apiCalls').textContent = state.stats.apiCalls;
            document.getElementById('wsBytes').textContent = (state.stats.wsBytes/1024).toFixed(2)+' KB';
            document.getElementById('oppCount').textContent = state.stats.oppCount;
            document.getElementById('megaCount').textContent = state.opportunities.mega.length;
            document.getElementById('triangularCount').textContent = state.opportunities.triangular.length;
            document.getElementById('bellmanCount').textContent = state.opportunities.bellman.length;
            document.getElementById('microCount').textContent = state.opportunities.micro.length;
            document.getElementById('bankroll').textContent = '$'+state.bankroll.toFixed(2);
            const pnlPercent = ((state.bankroll-10000)/10000*100).toFixed(2);
            document.getElementById('pnl').innerHTML = `$${(state.bankroll-10000).toFixed(2)} (${pnlPercent}%)`;
            document.getElementById('pnl').style.color = (state.bankroll>=10000)?'#00ff00':'#ff4444';
        }
        function toggleLogs() { document.getElementById('logs').style.display = document.getElementById('logs').style.display==='none'?'block':'none'; }
        function toggleSection(id) { const el=document.getElementById(id); el.style.display = el.style.display==='none'?'block':'none'; }
        function updateBetDisplay() { document.getElementById('betDisplay').textContent = '$'+Number(document.getElementById('betSlider').value).toLocaleString(); }

        // ==================== EXCHANGE LOADERS (16+ real sources) ====================
        async function loadOKX() {
            try {
                const resp = await fetch('https://www.okx.com/api/v5/market/tickers?instType=SPOT');
                if(!resp.ok) throw new Error();
                const data = await resp.json(); state.stats.apiCalls++;
                state.exchanges.okx = { name:'OKX', status:'online', pairs: data.data.slice(0,400).map(t=>{
                    const parts = t.instId.split('-'); if(parts.length!==2) return null;
                    const price = parseFloat(t.last)||0; const vol = parseFloat(t.volCcy24h)*price||0;
                    return { base:parts[0], target:parts[1], price, volume:vol, liquidity:vol, bidPrice:price*0.999, askPrice:price*1.001, exchange:'okx' };
                }).filter(p=>p&&p.price>0) };
            } catch(e) { state.exchanges.okx = { name:'OKX', status:'offline', pairs:[] }; log('OKX offline','error'); }
        }
        async function loadCoinbase() {
            try {
                const resp = await fetch('https://api.exchange.coinbase.com/products');
                if(!resp.ok) throw new Error();
                const data = await resp.json(); state.stats.apiCalls++;
                state.exchanges.coinbase = { name:'Coinbase', status:'online', pairs: data.slice(0,300).map(p=>({ base:p.base_currency, target:p.quote_currency, price:1, volume:0, liquidity:0, bidPrice:1*0.998, askPrice:1*1.002, exchange:'coinbase' })) };
            } catch(e) { state.exchanges.coinbase = { name:'Coinbase', status:'offline', pairs:[] }; log('Coinbase offline','error'); }
        }
        async function loadDexScreenerAll() {
            try {
                const chains = ['ethereum','bsc','solana','arbitrum','polygon','avalanche'];
                let allPairs = [];
                for(const chain of chains) {
                    const resp = await fetch(`https://api.dexscreener.com/latest/dex/pairs/${chain}`);
                    if(!resp.ok) continue;
                    const data = await resp.json(); state.stats.apiCalls++;
                    const pairs = (data.pairs||[]).slice(0,200).map(p=>{
                        const price = parseFloat(p.priceUsd)||0;
                        const liq = p.liquidity?.usd||0;
                        return { base:p.baseToken?.symbol||'UNKNOWN', target:p.quoteToken?.symbol||'USD', price, volume:p.volume?.h24||0, liquidity:liq, bidPrice:price*0.998, askPrice:price*1.002, exchange:`dexscreener_${chain}` };
                    }).filter(p=>p.base!=='UNKNOWN'&&p.price>0);
                    allPairs.push(...pairs);
                }
                state.exchanges.dexscreener = { name:'DexScreener (multi)', status:'online', pairs:allPairs };
            } catch(e) { state.exchanges.dexscreener = { name:'DexScreener', status:'offline', pairs:[] }; log('DexScreener offline','error'); }
        }
        async function loadPumpFun() {
            try {
                // Use DexScreener solana pairs which include pump.fun tokens
                const resp = await fetch('https://api.dexscreener.com/latest/dex/pairs/solana');
                if(!resp.ok) throw new Error();
                const data = await resp.json(); state.stats.apiCalls++;
                const pumpPairs = (data.pairs||[]).filter(p=>p.baseToken?.address?.startsWith('0x')===false && p.priceUsd<0.001).slice(0,300).map(p=>({
                    base:p.baseToken?.symbol||'PUMP', target:'SOL', price:parseFloat(p.priceUsd)||0, volume:p.volume?.h24||0, liquidity:p.liquidity?.usd||0, bidPrice:parseFloat(p.priceUsd)*0.95, askPrice:parseFloat(p.priceUsd)*1.05, exchange:'pumpfun'
                })).filter(p=>p.price>0);
                state.exchanges.pumpfun = { name:'Pump.fun (via Dex)', status:'online', pairs:pumpPairs };
            } catch(e) { state.exchanges.pumpfun = { name:'Pump.fun', status:'offline', pairs:[] }; log('Pump.fun offline','error'); }
        }
        async function loadYobit() {
            try {
                const resp = await fetch('https://yobit.net/api/3/ticker/btc_usd?ignore=1');
                if(!resp.ok) throw new Error();
                const data = await resp.json(); state.stats.apiCalls++;
                state.exchanges.yobit = { name:'Yobit', status:'online', pairs: [{ base:'BTC', target:'USD', price:data.btc_usd?.last||60000, volume:0, liquidity:0, bidPrice:data.btc_usd?.buy||60000*0.99, askPrice:data.btc_usd?.sell||60000*1.01, exchange:'yobit' }] };
            } catch(e) { state.exchanges.yobit = { name:'Yobit', status:'offline', pairs:[] }; log('Yobit offline','error'); }
        }
        async function loadAlpaca() {
            try {
                const resp = await fetch('https://data.alpaca.markets/v1beta3/crypto/latest/trades?symbols=BTC/USD,ETH/USD');
                if(!resp.ok) throw new Error();
                const data = await resp.json(); state.stats.apiCalls++;
                const pairs = [];
                if(data.trades?.['BTC/USD']) pairs.push({ base:'BTC', target:'USD', price:data.trades['BTC/USD'].p, volume:0, liquidity:0, bidPrice:data.trades['BTC/USD'].p*0.998, askPrice:data.trades['BTC/USD'].p*1.002, exchange:'alpaca' });
                if(data.trades?.['ETH/USD']) pairs.push({ base:'ETH', target:'USD', price:data.trades['ETH/USD'].p, volume:0, liquidity:0, bidPrice:data.trades['ETH/USD'].p*0.998, askPrice:data.trades['ETH/USD'].p*1.002, exchange:'alpaca' });
                state.exchanges.alpaca = { name:'Alpaca', status:'online', pairs };
            } catch(e) { state.exchanges.alpaca = { name:'Alpaca', status:'offline', pairs:[] }; log('Alpaca offline','error'); }
        }
        async function loadIndodax() {
            try {
                const resp = await fetch('https://indodax.com/api/tickers');
                if(!resp.ok) throw new Error();
                const data = await resp.json(); state.stats.apiCalls++;
                const pairs = Object.entries(data).slice(0,50).map(([sym,val])=>({ base:sym.split('_')[0]?.toUpperCase()||sym, target:sym.split('_')[1]?.toUpperCase()||'IDR', price:parseFloat(val.last)||0, volume:parseFloat(val.vol_btc)||0, liquidity:0, bidPrice:parseFloat(val.buy)||0, askPrice:parseFloat(val.sell)||0, exchange:'indodax' })).filter(p=>p.price>0);
                state.exchanges.indodax = { name:'Indodax', status:'online', pairs };
            } catch(e) { state.exchanges.indodax = { name:'Indodax', status:'offline', pairs:[] }; log('Indodax offline','error'); }
        }
        async function loadBinance() {
            try {
                const resp = await fetch('https://api.binance.com/api/v3/ticker/price');
                if(!resp.ok) throw new Error();
                const data = await resp.json(); state.stats.apiCalls++;
                const pairs = data.slice(0,200).map(t=>({ base:t.symbol.replace(/USDT|BTC|ETH/,''), target:t.symbol.slice(-4), price:parseFloat(t.price)||0, volume:0, liquidity:0, bidPrice:parseFloat(t.price)*0.998, askPrice:parseFloat(t.price)*1.002, exchange:'binance' })).filter(p=>p.price>0);
                state.exchanges.binance = { name:'Binance', status:'online', pairs };
            } catch(e) { state.exchanges.binance = { name:'Binance', status:'offline', pairs:[] }; log('Binance offline','error'); }
