                const resp = await fetch('https://api.kucoin.com/api/v1/market/allTickers');
                if(!resp.ok) throw new Error();
                const data = await resp.json(); state.stats.apiCalls++;
                const pairs = (data.data?.ticker||[]).slice(0,200).map(t=>({ base:t.symbol.split('-')[0], target:t.symbol.split('-')[1], price:parseFloat(t.last)||0, volume:parseFloat(t.vol)||0, liquidity:0, bidPrice:parseFloat(t.buy)||0, askPrice:parseFloat(t.sell)||0, exchange:'kucoin' })).filter(p=>p.base&&p.target&&p.price>0);
                state.exchanges.kucoin = { name:'KuCoin', status:'online', pairs };
            } catch(e) { state.exchanges.kucoin = { name:'KuCoin', status:'offline', pairs:[] }; log('KuCoin offline','error'); }
