        @media (max-width:768px) { .grid { grid-template-columns: 1fr; } .controls { justify-content: center; } }
    </style>
</head>
<body>
    <canvas id="particleCanvas"></canvas>
    <div class="container">
        <div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap;">
            <h1>🎰 QUANTM FOAM <span style="font-size:12px;">v11.0 | ARBITRAGE CASINO + REGINTEL</span></h1>
            <button id="themeToggle" class="neon-btn" style="padding:4px 8px;">🎨 THEME</button>
        </div>
        <div class="status-bar" id="mainStatus">🟡 READY TO SPIN</div>

        <div class="controls">
            <button class="neon-btn cyan" onclick="initSystem()">🔄 INITIALIZE</button>
            <button id="scanBtn" class="neon-btn" onclick="runFullScan()" disabled>🎲 FULL SCAN</button>
            <button class="neon-btn" onclick="scanMicroCaps()">💎 MICRO CAPS</button>
            <button class="neon-btn cyan" onclick="connectWebSockets()">📡 LIVE STREAM</button>
            <button class="neon-btn" onclick="toggleLogs()">📋 LOGS</button>
            <button class="neon-btn cyan" onclick="shareJackpot()">📤 SHARE</button>
        </div>

        <div class="flex-row" style="margin:10px 0; background:#1a1a2a; padding:10px; border-radius:10px;">
            <span style="color:var(--gold);">💰 BANKROLL:</span>
            <span class="rolling-number" id="bankroll">$10,000.00</span>
            <span style="margin-left:auto; color:var(--neon-cyan);">📈 TODAY'S P/L:</span>
            <span id="pnl" style="color:var(--neon-green);">$0.00 (0.00%)</span>
        </div>

        <div class="tab">
            <button class="tab-btn active" data-tab="arb">🎰 ARBITRAGE ENGINE</button>
            <button class="tab-btn" data-tab="reg">⚕️ REGULATORY INTELLIGENCE</button>
        </div>

        <!-- ARBITRAGE TAB -->
        <div id="arbTab" class="tab-content active">
            <div class="grid" id="exchangeStatus"></div>
            <div class="grid">
                <div class="card"><h3>🔥 ULTRA LOW (&lt;$0.0001)</h3><div id="ultraLowValue" style="max-height:200px; overflow-y:auto;"></div></div>
                <div class="card"><h3>💧 MICRO CAP (&lt;$0.001)</h3><div id="microCap" style="max-height:200px; overflow-y:auto;"></div></div>
                <div class="card">
                    <h3>📊 STATISTICS</h3>
                    <div class="stat"><span>Pairs:</span><span class="stat-value" id="totalPairs">0</span></div>
                    <div class="stat"><span>Nodes:</span><span class="stat-value" id="graphNodes">0</span></div>
                    <div class="stat"><span>Edges:</span><span class="stat-value" id="graphEdges">0</span></div>
                    <div class="stat"><span>Triangles:</span><span class="stat-value" id="triangleCount">0</span></div>
                    <div class="stat"><span>API Calls:</span><span class="stat-value" id="apiCalls">0</span></div>
                    <div class="stat"><span>WS Bytes:</span><span class="stat-value" id="wsBytes">0 KB</span></div>
                    <div class="stat"><span>Opps:</span><span class="stat-value rolling-number" id="oppCount">0</span></div>
                </div>
            </div>
            <div class="flex-row"><label style="color:var(--neon-cyan);">🎚️ BET SIZE:</label><input type="range" class="bet-slider" id="betSlider" min="100" max="10000" value="1000" step="100" oninput="updateBetDisplay()"><span id="betDisplay" style="color:var(--gold);">$1,000</span></div>
            <div class="opp-section"><div class="opp-header" onclick="toggleSection('megaOpps')">🌟 MEGA JACKPOTS (&gt;5%) <span id="megaCount">0</span></div><div id="megaOpps" class="opp-list"></div></div>
            <div class="opp-section"><div class="opp-header" onclick="toggleSection('triangularOpps')">📐 TRIANGULAR <span id="triangularCount">0</span></div><div id="triangularOpps" class="opp-list"></div></div>
            <div class="opp-section"><div class="opp-header" onclick="toggleSection('bellmanOpps')">🔍 BELLMAN-FORD <span id="bellmanCount">0</span></div><div id="bellmanOpps" class="opp-list"></div></div>
            <div class="opp-section"><div class="opp-header" onclick="toggleSection('microOpps')">💎 MICRO OPPORTUNITIES <span id="microCount">0</span></div><div id="microOpps" class="opp-list"></div></div>
        </div>

        <!-- REGULATORY INTELLIGENCE TAB (merged from peptide branch) -->
        <div id="regTab" class="tab-content">
            <div class="card">
                <h3 style="color:var(--gold);">🧬 GLOBAL REGULATORY MATRIX (Peptides / Hormones / Gene Therapies)</h3>
                <p style="font-size:10px; margin-bottom:8px;">Live data from FDA, EMA, WADA, and curated peptide DBs. Click row for details.</p>
                <div style="overflow-x:auto;">
                    <table id="regTable" style="width:100%; border-collapse:collapse; font-size:9px;">
                        <thead><tr style="background:#2a2a3a;"><th>Compound</th><th>Type</th><th>US Status</th><th>EU Status</th><th>WADA</th></tr></thead>
                        <tbody id="regTbody"><tr><td colspan="5">Loading regulatory data...</td></tr></tbody>
                    </table>
                </div>
                <div class="flex-row" style="margin-top:10px;"><button class="neon-btn" onclick="refreshRegulatory()">🔄 Refresh Regulatory</button></div>
            </div>
        </div>

        <h2 style="cursor:pointer;" onclick="toggleLogs()">📜 SYSTEM LOGS</h2>
        <div class="log-container" id="logs" style="display:none;"></div>
    </div>

    <!-- Trade Modal -->
    <div id="tradeModal" class="modal"><div class="modal-content"><h3 style="color:var(--gold);">🎰 EXECUTE ARBITRAGE</h3><div id="tradeDetails"></div><div style="margin-top:15px; display:flex; gap:10px; justify-content:flex-end;"><button class="neon-btn" onclick="closeModal()">CANCEL</button><button class="neon-btn cyan" id="executeTradeBtn">💸 PULL LEVER</button></div></div></div>

    <script>
        // ==================== GLOBAL CONFIG & STATE ====================
        let state = {
            exchanges: {},
            opportunities: { mega:[], triangular:[], bellman:[], micro:[] },
            stats: { totalPairs:0, graphNodes:0, graphEdges:0, triangleCount:0, apiCalls:0, wsBytes:0, oppCount:0 },
            systemReady: false, graph: {}, triangles: [], allPairs: [],
            bankroll: 10000, pnl: 0, trades: [], lastScanTime: 0
        };
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        function playTone(freq, duration, type='square', vol=0.1) { try { const osc=audioCtx.createOscillator(); const gain=audioCtx.createGain(); osc.type=type; osc.frequency.value=freq; gain.gain.setValueAtTime(vol,audioCtx.currentTime); gain.gain.exponentialRampToValueAtTime(0.001,audioCtx.currentTime+duration); osc.connect(gain); gain.connect(audioCtx.destination); osc.start(); osc.stop(audioCtx.currentTime+duration); } catch(e){} }
        function playSpinSound() { playTone(800,0.1,'sawtooth',0.05); }
        function playWinSound() { playTone(523,0.15,'square',0.1); setTimeout(()=>playTone(659,0.15,'square',0.1),150); setTimeout(()=>playTone(784,0.25,'square',0.1),300); }
        function playJackpotSound() { [523,659,784,1047].forEach((f,i)=>setTimeout(()=>playTone(f,0.3,'square',0.15),i*150)); }

        // Particles
        const canvas=document.getElementById('particleCanvas'), ctx=canvas.getContext('2d');
        let particles=[];
        function resizeCanvas(){ canvas.width=window.innerWidth; canvas.height=window.innerHeight; }
        window.addEventListener('resize',resizeCanvas); resizeCanvas();
        function animateParticles(){
            ctx.clearRect(0,0,canvas.width,canvas.height);
            for(let i=particles.length-1;i>=0;i--){
                const p=particles[i]; p.x+=p.vx; p.y+=p.vy; p.vy+=0.1; p.life-=0.02;
                ctx.fillStyle=p.color; ctx.globalAlpha=p.life; ctx.fillRect(p.x,p.y,4,4);
                if(p.life<=0) particles.splice(i,1);
            }
            requestAnimationFrame(animateParticles);
        }
        animateParticles();
        function spawnConfetti(x,y,count=30){
            const colors=['#ff00ff','#00f0ff','#ffd700','#00ffaa'];
            for(let i=0;i<count;i++) particles.push({x,y,vx:(Math.random()-0.5)*8,vy:(Math.random()-0.5)*8-3,color:colors[Math.floor(Math.random()*colors.length)],life:0.8+Math.random()*0.4});
        }

        // UI Helpers
        function log(msg,type){ const t=new Date().toLocaleTimeString(); const el=document.getElementById('logs'); el.innerHTML=`<div class="log-entry ${type||'info'}">[${t}] ${msg}</div>`+el.innerHTML; console.log(`[${t}] ${msg}`); }
        function updateStatus(msg){ document.getElementById('mainStatus').innerHTML=msg; }
        function updateStats(){
            document.getElementById('totalPairs').textContent=state.stats.totalPairs;
            document.getElementById('graphNodes').textContent=state.stats.graphNodes;
            document.getElementById('graphEdges').textContent=state.stats.graphEdges;
            document.getElementById('triangleCount').textContent=state.stats.triangleCount;
            document.getElementById('apiCalls').textContent=state.stats.apiCalls;
            document.getElementById('wsBytes').textContent=(state.stats.wsBytes/1024).toFixed(2)+' KB';
            document.getElementById('oppCount').textContent=state.stats.oppCount;
            document.getElementById('megaCount').textContent=state.opportunities.mega.length;
            document.getElementById('triangularCount').textContent=state.opportunities.triangular.length;
            document.getElementById('bellmanCount').textContent=state.opportunities.bellman.length;
            document.getElementById('microCount').textContent=state.opportunities.micro.length;
            document.getElementById('bankroll').textContent='$'+state.bankroll.toFixed(2);
            const pnlPercent=((state.bankroll-10000)/10000*100).toFixed(2);
            document.getElementById('pnl').innerHTML=`$${(state.bankroll-10000).toFixed(2)} (${pnlPercent}%)`;
            document.getElementById('pnl').style.color=state.bankroll>=10000?'#00ff00':'#ff4444';
        }
        function toggleLogs(){ document.getElementById('logs').style.display=document.getElementById('logs').style.display==='none'?'block':'none'; }
        function toggleSection(id){ const el=document.getElementById(id); el.style.display=el.style.display==='none'?'block':'none'; }
        function updateBetDisplay(){ document.getElementById('betDisplay').textContent='$'+Number(document.getElementById('betSlider').value).toLocaleString(); }
        function closeModal(){ document.getElementById('tradeModal').style.display='none'; }
        function shareJackpot(){
            const mega=state.opportunities.mega[0];
            if(mega){ navigator.clipboard.writeText(`🎰 I found a ${mega.profitPercent.toFixed(2)}% arb on QuanTM FOAM! Path: ${mega.path.join('→')} #DeFi`).then(()=>log('📤 Copied!','success'));}
            else log('No jackpot','warning');
        }
        let themeFlip=false;
        document.getElementById('themeToggle').onclick=()=>{ document.body.style.filter=themeFlip?'none':'hue-rotate(180deg)'; themeFlip=!themeFlip; };

        // Tab switching
        document.querySelectorAll('.tab-btn').forEach(btn=>{
            btn.addEventListener('click',()=>{
                document.querySelectorAll('.tab-btn').forEach(b=>b.classList.remove('active'));
                document.querySelectorAll('.tab-content').forEach(t=>t.classList.remove('active'));
                btn.classList.add('active');
                document.getElementById(btn.dataset.tab+'Tab').classList.add('active');
                if(btn.dataset.tab==='reg' && state.regDataLoaded!==true) loadRegulatoryData();
            });
        });

        // ==================== EXCHANGE LOADERS (13+ real APIs) ====================
        async function loadExchange(name, fetchFn){
            try { const result = await fetchFn(); return result; } catch(e){ log(`${name} failed: ${e.message}`,'error'); return false; }
        }
        async function loadBinance(){
            const res=await fetch('https://api.binance.com/api/v3/ticker/24hr');
            if(!res.ok) throw new Error('HTTP '+res.status);
            const data=await res.json(); state.stats.apiCalls++;
            return data.slice(0,400).map(t=>{
                const sym=t.symbol;
                let base='',target='';
                if(sym.endsWith('USDT')){ base=sym.slice(0,-4); target='USDT'; }
                else if(sym.endsWith('BTC')){ base=sym.slice(0,-3); target='BTC'; }
                else return null;
                const price=parseFloat(t.lastPrice)||0;
                const vol=parseFloat(t.quoteVolume)||0;
                const spread=vol>0?Math.max(0.0005,Math.min(0.01,50000/vol)):0.01;
                return { base, target, price, volume:vol, liquidity:vol, bidPrice:price*(1-spread/2), askPrice:price*(1+spread/2), spread, exchange:'binance' };
            }).filter(p=>p&&p.price>0);
        }
        async function loadOKX(){
            const res=await fetch('https://www.okx.com/api/v5/market/tickers?instType=SPOT');
            if(!res.ok) throw new Error('HTTP '+res.status);
            const data=await res.json(); state.stats.apiCalls++;
            return data.data.slice(0,500).map(t=>{
                const parts=t.instId.split('-'); if(parts.length!==2) return null;
                const price=parseFloat(t.last)||0;
                const vol=parseFloat(t.volCcy24h)*price||0;
                return { base:parts[0], target:parts[1], price, volume:vol, liquidity:vol, bidPrice:parseFloat(t.bidPx)||price*0.999, askPrice:parseFloat(t.askPx)||price*1.001, spread:0.002, exchange:'okx' };
            }).filter(p=>p&&p.price>0);
        }
        async function loadCoinbase(){
            const res=await fetch('https://api.exchange.coinbase.com/products');
            if(!res.ok) throw new Error('HTTP '+res.status);
            const data=await res.json(); state.stats.apiCalls++;
            return data.slice(0,300).map(p=>({ base:p.base_currency, target:p.quote_currency, price:p.price||1, volume:p.volume||0, liquidity:p.volume||0, bidPrice:p.price*0.998, askPrice:p.price*1.002, spread:0.004, exchange:'coinbase' })).filter(p=>p.price>0);
        }
        async function loadKraken(){
            const res=await fetch('https://api.kraken.com/0/public/Ticker');
            if(!res.ok) throw new Error();
            const data=await res.json(); state.stats.apiCalls++;
            return Object.entries(data.result).map(([pair,val])=>{
                if(!pair.endsWith('USD')) return null;
                const base=pair.slice(0,-3);
                const price=parseFloat(val.c[0])||0;
                const vol=parseFloat(val.v[1])*price||0;
                return { base, target:'USD', price, volume:vol, liquidity:vol, bidPrice:parseFloat(val.b[0])||price*0.998, askPrice:parseFloat(val.a[0])||price*1.002, spread:0.004, exchange:'kraken' };
            }).filter(p=>p&&p.price>0);
        }
        async function loadKuCoin(){
            const res=await fetch('https://api.kucoin.com/api/v1/market/allTickers');
            if(!res.ok) throw new Error();
            const data=await res.json(); state.stats.apiCalls++;
            return data.data.ticker.slice(0,400).map(t=>{
                const sym=t.symbol;
                const [base,target]=sym.split('-');
                if(!base||!target) return null;
                const price=parseFloat(t.last)||0;
                const vol=parseFloat(t.vol)||0;
                return { base, target, price, volume:vol, liquidity:vol, bidPrice:parseFloat(t.buy)||price*0.998, askPrice:parseFloat(t.sell)||price*1.002, spread:0.003, exchange:'kucoin' };
            }).filter(p=>p&&p.price>0);
        }
        async function loadBybit(){
            const res=await fetch('https://api.bybit.com/v5/market/tickers?category=spot');
            if(!res.ok) throw new Error();
            const data=await res.json(); state.stats.apiCalls++;
            return data.result.list.slice(0,300).map(t=>{
                const [base,target]=t.symbol.split('USDT');
                if(!base||!target) return null;
                const price=parseFloat(t.lastPrice)||0;
                const vol=parseFloat(t.volume24h)*price||0;
                return { base, target:'USDT', price, volume:vol, liquidity:vol, bidPrice:parseFloat(t.bid1Price)||price*0.998, askPrice:parseFloat(t.ask1Price)||price*1.002, spread:0.003, exchange:'bybit' };
            }).filter(p=>p&&p.price>0);
        }
        async function loadYobit(){
            const res=await fetch('https://yobit.net/api/3/info');
            if(!res.ok) throw new Error();
            const data=await res.json(); state.stats.apiCalls++;
            const pairs=Object.keys(data.pairs);
            const pricePromises = pairs.slice(0,100).map(async pair=>{
                const [base,target]=pair.split('_');
                if(!base||!target) return null;
                const tick=await fetch(`https://yobit.net/api/3/ticker/${pair}`).then(r=>r.json()).catch(()=>null);
                if(!tick) return null;
                const price=parseFloat(tick[pair].last);
                return { base, target, price, volume:tick[pair].vol_cur||0, liquidity:tick[pair].vol_cur*price||0, bidPrice:price*0.99, askPrice:price*1.01, spread:0.01, exchange:'yobit' };
            });
            const results=await Promise.all(pricePromises);
            return results.filter(p=>p&&p.price>0);
        }
        async function loadIndodax(){
            const res=await fetch('https://indodax.com/api/tickers');
            if(!res.ok) throw new Error();
            const data=await res.json(); state.stats.apiCalls++;
            return Object.entries(data).slice(0,200).map(([pair,val])=>{
                if(!pair.endsWith('_idr')) return null;
                const base=pair.slice(0,-4);
                const price=parseFloat(val.last)||0;
                const vol=parseFloat(val.vol_base)||0;
                return { base, target:'IDR', price, volume:vol, liquidity:vol*price||0, bidPrice:price*0.998, askPrice:price*1.002, spread:0.004, exchange:'indodax' };
            }).filter(p=>p&&p.price>0);
        }
        async function loadAlpaca(){
            // Public crypto data (no key required for some endpoints)
            const res=await fetch('https://data.alpaca.markets/v1beta3/crypto/latest/trades?symbols=BTC/USD,ETH/USD,SOL/USD,MATIC/USD');
            if(!res.ok) throw new Error();
            const data=await res.json(); state.stats.apiCalls++;
            return Object.entries(data.trades).map(([sym,val])=>{
                const [base,target]=sym.split('/');
                const price=val[0]?.p||0;
                return { base, target, price, volume:0, liquidity:0, bidPrice:price*0.995, askPrice:price*1.005, spread:0.01, exchange:'alpaca' };
            }).filter(p=>p.price>0);
        }
        async function loadDexScreenerAll(){
            const chains = ['ethereum','bsc','solana','arbitrum','optimism','polygon','base','avalanche','fantom','cronos','gnosis'];
            let allPairs=[];
            for(const chain of chains){
                try{
                    const res=await fetch(`https://api.dexscreener.com/latest/dex/pairs/${chain}`);
                    if(res.ok){ const data=await res.json(); state.stats.apiCalls++; allPairs.push(...(data.pairs||[])); }
                }catch(e){}
            }
            return allPairs.map(p=>{
                const price=parseFloat(p.priceUsd)||0;
                const liq=p.liquidity?.usd||0;
                const spread=liq>0?Math.max(0.003,Math.min(0.03,5000/liq)):0.03;
                return { base:p.baseToken?.symbol||'UNKNOWN', target:p.quoteToken?.symbol||'ETH', price, volume:p.volume?.h24||0, liquidity:liq, bidPrice:price*(1-spread/2), askPrice:price*(1+spread/2), spread, exchange:`dex_${p.dexId||chain}` };
            }).filter(p=>p.base!=='UNKNOWN'&&p.price>0);
        }
        async function loadPumpFun(){
            try{
                const res=await fetch('https://frontend-api.pump.fun/coins?offset=0&limit=100&sort=created_timestamp&order=DESC');
                if(!res.ok) throw new Error();
                const data=await res.json(); state.stats.apiCalls++;
                return data.map(t=>{
                    const price=parseFloat(t.usd_market_cap)/parseFloat(t.total_supply)||0;
                    const liq=parseFloat(t.usd_market_cap)*0.1||0;
                    return { base:t.symbol||'UNKNOWN', target:'SOL', price, volume:liq*0.5, liquidity:liq, bidPrice:price*0.95, askPrice:price*1.05, spread:0.10, exchange:'pumpfun' };
                }).filter(p=>p.base!=='UNKNOWN'&&p.price>0);
            } catch(e){ return []; }
        }

        // ==================== DATA INITIALIZATION ====================
        async function initSystem(){
            log('🎰 INITIALIZING 13+ EXCHANGES...','info'); updateStatus('🔄 LOADING...');
            const exchangeLoaders = [
                {name:'Binance',fn:loadBinance},{name:'OKX',fn:loadOKX},{name:'Coinbase',fn:loadCoinbase},{name:'Kraken',fn:loadKraken},
                {name:'KuCoin',fn:loadKuCoin},{name:'Bybit',fn:loadBybit},{name:'Yobit',fn:loadYobit},{name:'Indodax',fn:loadIndodax},
                {name:'Alpaca',fn:loadAlpaca},{name:'DexScreener',fn:loadDexScreenerAll},{name:'Pump.fun',fn:loadPumpFun}
            ];
            state.exchanges = {};
            state.allPairs = [];
            for(const loader of exchangeLoaders){
                const pairs = await loadExchange(loader.name, loader.fn);
                if(pairs && pairs.length){
                    state.exchanges[loader.name.toLowerCase()] = { name:loader.name, status:'online', pairs, bytesReceived:0 };
                    state.allPairs.push(...pairs);
                } else {
                    state.exchanges[loader.name.toLowerCase()] = { name:loader.name, status:'offline', pairs:[], bytesReceived:0 };
                }
            }
            state.stats.totalPairs = state.allPairs.length;
            buildGraph(); buildTriangles(); displayLowValue();
            updateExchangeDisplay(); updateStats();
            const online = Object.values(state.exchanges).filter(e=>e.status==='online').length;
            if(online>0){ state.systemReady=true; document.getElementById('scanBtn').disabled=false; updateStatus(`✅ READY - ${online}/11 online`); log('🎰 SYSTEM READY','success'); playSpinSound(); }
            else { updateStatus('❌ NO EXCHANGES'); log('INIT FAILED','error'); }
        }
        function updateExchangeDisplay(){
            const container=document.getElementById('exchangeStatus');
            container.innerHTML='';
            Object.values(state.exchanges).forEach(ex=>{
                container.innerHTML+=`<div class="exchange-status"><div class="indicator ${ex.status==='online'?'online':''}"></div><div><strong>${ex.name}</strong><br><small>${ex.status.toUpperCase()} · ${ex.pairs.length} pairs</small></div></div>`;
            });
        }
        function buildGraph(){
            state.graph={}; let edges=0; const minLiq=100;
            state.allPairs.forEach(p=>{
                if(p.liquidity<minLiq) return;
                if(!state.graph[p.base]) state.graph[p.base]={};
                if(!state.graph[p.target]) state.graph[p.target]={};
                state.graph[p.base][p.target]={ rate:1/p.askPrice, weight:-Math.log(1/p.askPrice), volume:p.volume, liquidity:p.liquidity, spread:p.spread, exchange:p.exchange };
                edges++;
                state.graph[p.target][p.base]={ rate:p.bidPrice, weight:-Math.log(p.bidPrice), volume:p.volume, liquidity:p.liquidity, spread:p.spread, exchange:p.exchange };
                edges++;
            });
            state.stats.graphNodes=Object.keys(state.graph).length;
            state.stats.graphEdges=edges;
        }
        function buildTriangles(){
            state.triangles=[];
            const nodes=Object.keys(state.graph);
            for(let i=0;i<Math.min(nodes.length,100);i++){
                const A=nodes[i]; const neighborsA=Object.keys(state.graph[A]||{});
                for(const B of neighborsA){
                    const neighborsB=Object.keys(state.graph[B]||{});
                    for(const C of neighborsB) if(state.graph[C]&&state.graph[C][A]) state.triangles.push([A,B,C]);
                }
            }
            state.stats.triangleCount=state.triangles.length;
        }
        function displayLowValue(){
            const ultra=state.allPairs.filter(p=>p.price<0.0001&&p.price>0&&p.liquidity>=10).sort((a,b)=>a.price-b.price).slice(0,20);
            const micro=state.allPairs.filter(p=>p.price<0.001&&p.price>=0.0001&&p.liquidity>=10).sort((a,b)=>a.price-b.price).slice(0,20);
            document.getElementById('ultraLowValue').innerHTML=ultra.length?ultra.map(c=>`<div style="display:flex;justify-content:space-between;padding:2px 0;"><span>${c.base} (${c.exchange})</span><span>$${c.price.toFixed(10)}</span></div>`).join(''):'None';
            document.getElementById('microCap').innerHTML=micro.length?micro.map(c=>`<div style="display:flex;justify-content:space-between;padding:2px 0;"><span>${c.base} (${c.exchange})</span><span>$${c.price.toFixed(8)}</span></div>`).join(''):'None';
        }

        // ==================== ARBITRAGE SCANNING ====================
        function calculateMaxTradeSize(edges){ return Math.min(...edges.map(e=>e.liquidity))*0.05; }
        function scanTriangular(minProfit=0.0001){
            const opps=[], baseInv=1000;
            state.triangles.forEach(([A,B,C])=>{
                const e1=state.graph[A]?.[B], e2=state.graph[B]?.[C], e3=state.graph[C]?.[A];
                if(!e1||!e2||!e3) return;
                const final=baseInv*e1.rate*e2.rate*e3.rate;
                const profit=final-baseInv, pct=(profit/baseInv)*100;
                if(pct>=minProfit){
                    const maxSize=calculateMaxTradeSize([e1,e2,e3]);
                    opps.push({type:'triangular', path:[A,B,C,A], profitPercent:pct, profit, actualProfit:(maxSize/baseInv)*profit, maxTradeSize:maxSize, totalLiquidity:Math.min(e1.liquidity,e2.liquidity,e3.liquidity), edges:[e1,e2,e3] });
                }
            });
            return opps;
        }
        function bellmanFord(startCurr, maxPath=5){
            const currencies=Object.keys(state.graph);
            if(!currencies.includes(startCurr)) return [];
            const dist={}, pred={};
            currencies.forEach(c=>{ dist[c]=Infinity; pred[c]=null; });
            dist[startCurr]=0;
            for(let i=0;i<Math.min(maxPath-1,currencies.length-1);i++){
                let updated=false;
                for(const u of currencies){
                    const neighbors=state.graph[u]; if(!neighbors) continue;
                    for(const v in neighbors){
                        const w=neighbors[v].weight;
                        if(dist[u]!==Infinity && dist[u]+w<dist[v]){ dist[v]=dist[u]+w; pred[v]=u; updated=true; }
                    }
                }
                if(!updated) break;
            }
            const opps=[];
            for(const u of currencies){
                const neighbors=state.graph[u]; if(!neighbors) continue;
                for(const v in neighbors){
                    if(dist[u]!==Infinity && dist[u]+neighbors[v].weight<dist[v]){
                        const cycle=reconstructCycle(v,pred,maxPath);
                        if(cycle&&cycle.length>=3&&cycle[0]===startCurr){
                            const opp=calculateCycleOpp(cycle);
                            if(opp) opps.push(opp);
                        }
                    }
                }
            }
            return opps;
        }
        function reconstructCycle(start,pred,maxLen){
            const cycle=[start]; let curr=pred[start]; const visited=new Set([start]);
            while(curr&&!visited.has(curr)&&cycle.length<maxLen){ cycle.unshift(curr); visited.add(curr); curr=pred[curr]; }
            return cycle.length>=3?cycle:null;
        }
        function calculateCycleOpp(cycle){
            let amount=1000; const edges=[]; let totalLiq=Infinity;
            for(let i=0;i<cycle.length-1;i++){
                const edge=state.graph[cycle[i]]?.[cycle[i+1]]; if(!edge) return null;
                amount*=edge.rate; edges.push(edge); totalLiq=Math.min(totalLiq,edge.liquidity);
            }
            const lastEdge=state.graph[cycle[cycle.length-1]]?.[cycle[0]]; if(!lastEdge) return null;
            amount*=lastEdge.rate; edges.push(lastEdge); totalLiq=Math.min(totalLiq,lastEdge.liquidity);
            const profit=amount-1000, pct=(profit/1000)*100;
            if(pct>=0.0001&&totalLiq>=100){
                const maxSize=calculateMaxTradeSize(edges);
                return { type:'bellman-ford', path:cycle, profitPercent:pct, profit, actualProfit:(maxSize/1000)*profit, maxTradeSize:maxSize, totalLiquidity:totalLiq, edges };
            }
            return null;
        }
        async function runFullScan(){
            if(!state.systemReady) return log('System not ready','error');
            const now=Date.now(); if(now-state.lastScanTime<2000) return log('Please wait 2 seconds','warning');
            state.lastScanTime=now;
            log('🎲 SPINNING THE WHEEL...','info'); updateStatus('🎰 SCANNING...'); playSpinSound();
            state.opportunities={mega:[],triangular:[],bellman:[],micro:[]};
            const triOpps=scanTriangular(0.0001);
            const bfOpps=[];
            const topCur={};
            state.allPairs.forEach(p=>{ if(!topCur[p.base]) topCur[p.base]=0; topCur[p.base]+=p.volume; });
            const sortedCur=Object.keys(topCur).sort((a,b)=>topCur[b]-topCur[a]).slice(0,30);
            for(const c of sortedCur) bfOpps.push(...bellmanFord(c,5));
            const seen=new Set();
            triOpps.forEach(o=>{ const key=o.path.slice().sort().join('-'); if(!seen.has(key)){ seen.add(key); o.profitPercent>5?state.opportunities.mega.push(o):state.opportunities.triangular.push(o); } });
            bfOpps.forEach(o=>{ const key=o.path.slice().sort().join('-'); if(!seen.has(key)){ seen.add(key); o.profitPercent>5?state.opportunities.mega.push(o):state.opportunities.bellman.push(o); } });
            state.stats.oppCount=Object.values(state.opportunities).flat().length;
            updateStats(); displayAllOpps();
            updateStatus(`✅ COMPLETE - ${state.stats.oppCount} OPPORTUNITIES`);
            if(state.opportunities.mega.length>0){ spawnConfetti(window.innerWidth/2,100,50); playJackpotSound(); }
            log('🎉 SCAN DONE','success');
        }
        async function scanMicroCaps(){
            if(!state.systemReady) return;
            const maxPrice=parseFloat(document.getElementById('maxPrice')?.value||0.001);
            const microPairs=state.allPairs.filter(p=>p.price<maxPrice&&p.price>0&&p.liquidity>=10);
            const tempGraph={};
            microPairs.forEach(p=>{
                if(!tempGraph[p.base]) tempGraph[p.base]={};
                if(!tempGraph[p.target]) tempGraph[p.target]={};
                tempGraph[p.base][p.target]={ rate:1/p.askPrice, weight:-Math.log(1/p.askPrice), volume:p.volume, liquidity:p.liquidity, spread:p.spread, exchange:p.exchange };
                tempGraph[p.target][p.base]={ rate:p.bidPrice, weight:-Math.log(p.bidPrice), volume:p.volume, liquidity:p.liquidity, spread:p.spread, exchange:p.exchange };
            });
            const orig=state.graph; state.graph=tempGraph;
            const currencies=Object.keys(tempGraph).slice(0,40);
            const opps=[];
            for(const c of currencies) opps.push(...bellmanFord(c,5));
            state.graph=orig;
            state.opportunities.micro=opps.sort((a,b)=>b.actualProfit-a.actualProfit);
            updateStats(); displayMicroOpps();
            log('💎 Micro-cap scan: '+opps.length,'success');
        }
        function displayAllOpps(){
            document.getElementById('megaOpps').innerHTML=state.opportunities.mega.slice(0,20).map(o=>renderOppCard(o,'mega')).join('');
            document.getElementById('triangularOpps').innerHTML=state.opportunities.triangular.slice(0,20).map(o=>renderOppCard(o,'')).join('');
            document.getElementById('bellmanOpps').innerHTML=state.opportunities.bellman.slice(0,20).map(o=>renderOppCard(o,'')).join('');
        }
        function displayMicroOpps(){
            document.getElementById('microOpps').innerHTML=state.opportunities.micro.slice(0,20).map(o=>renderOppCard(o,'micro')).join('');
        }
        function renderOppCard(opp,cls){
            const pathHtml = opp.edges.map((e,i)=>`<div>${opp.path[i]} → ${opp.path[i+1]} <span class="chip">${e.exchange}</span> Rate:${e.rate.toFixed(6)} Liq:$${e.liquidity.toFixed(0)}</div>`).join('');
            return `<div class="opportunity ${cls}" onclick="openTradeModal('${encodeURIComponent(JSON.stringify(opp))}')">
                <div style="display:flex;justify-content:space-between;"><strong>${opp.type.toUpperCase()}</strong><strong style="color:${opp.profitPercent>5?'var(--gold)':'var(--neon-green)'}">+${opp.profitPercent.toFixed(4)}%</strong></div>
                <div class="path-visual">${pathHtml}</div>
                <div class="depth-info">Max Trade: $${opp.maxTradeSize.toFixed(2)} · Actual Profit: $${opp.actualProfit.toFixed(4)}</div>
            </div>`;
        }
        function openTradeModal(oppStr){
            const opp=JSON.parse(decodeURIComponent(oppStr));
            const bet=parseFloat(document.getElementById('betSlider').value);
            const tradeSize=Math.min(opp.maxTradeSize,bet);
            const profit=(tradeSize/opp.maxTradeSize)*opp.actualProfit;
            const gasEst=20; const netProfit=profit-gasEst;
            document.getElementById('tradeDetails').innerHTML=`
                <p>🔄 <strong>${opp.path.join(' → ')}</strong></p><p>💰 Trade Size: $${tradeSize.toFixed(2)}</p>
                <p>📈 Gross Profit: $${profit.toFixed(4)}</p><p>⛽ Gas Estimate: $${gasEst.toFixed(2)}</p>
                <p style="color:${netProfit>0?'var(--neon-green)':'#ff4444'}">💵 Net Profit: $${netProfit.toFixed(4)}</p>
                <p style="color:var(--gold);">⚠️ MEV Risk: Medium</p>`;
            document.getElementById('executeTradeBtn').onclick=()=>executeTrade(opp,tradeSize,netProfit);
            document.getElementById('tradeModal').style.display='flex';
        }
        function executeTrade(opp,size,netProfit){
            state.bankroll+=netProfit;
            log(`🎰 TRADE EXECUTED: +$${netProfit.toFixed(2)} | Bankroll: $${state.bankroll.toFixed(2)}`, netProfit>0?'success':'error');
            updateStats(); closeModal();
            if(netProfit>50) spawnConfetti(window.innerWidth/2,200,100);
            playWinSound();
        }
        function connectWebSockets(){
            log('📡 Connecting OKX live...','info');
            try{
                const ws=new WebSocket('wss://ws.okx.com:8443/ws/v5/public');
                ws.onopen=()=>{ log('OKX Live ON','success'); ws.send(JSON.stringify({op:'subscribe',args:[{channel:'tickers',instType:'SPOT'}]})); };
                ws.onmessage=(e)=>{ state.exchanges.okx.bytesReceived+=e.data.length; state.stats.wsBytes+=e.data.length; };
                ws.onerror=()=>log('OKX WS error','error');
            } catch(e){ log('WS failed: '+e.message,'error'); }
            setInterval(updateStats,2000);
        }

        // ==================== REGULATORY INTELLIGENCE (merged branch) ====================
        let regDataLoaded=false;
